function makePlayer(pid,profile,index){const a={pid,base:profile.base,id:profile.base,job:profile.job,name:profile.name,index,x:0,y:0,prevX:0,prevY:0,vx:0,vy:0,r:15,level:5,xp:0,xpNext:95,points:0,talents:{power:0,vitality:0,utility:0},bag:{potion:3,ether:1},gear:[],coins:0,down:false,disconnected:false,dir:0,anim:0,action:null,hurt:0,inv:0,cool:0,q:0,e:0,rskill:0,dash:0,burst:0,buff:0,shield:0,revive:0,input:0,oldInput:0,interactCool:0,combat:0,regen:0};stats(a);a.hp=a.max;return a;}
function stats(a){const sp=S[a.id],c=C[a.job];let hp=1,speed=1,damage=1,crit=.05,electric=0,regen=0;for(const key of a.gear){const it=ITEMS[key];hp+=it.hp||0;speed+=it.speed||0;damage+=it.damage||0;crit+=it.crit||0;electric+=it.electric||0;regen+=it.regen||0;}a.max=Math.round((sp.hp+(a.level-5)*4+a.talents.vitality*12)*c.hp*hp);a.speed=clamp(sp.speed*c.speed*speed*(1+a.talents.utility*.025),140,290);a.damage=(17+(a.level-5)*1.8+a.talents.power*2.5)*c.dmg*damage*(sp.kind==='spark'?1+electric:1);a.crit=clamp(crit,0,.6);a.regenRate=regen;a.hp=Math.min(a.hp||a.max,a.max);}
