function evolve(a){let sp=S[a.id],id=sp.next;if(a.id===133&&a.level>=20)id={guardian:134,striker:135,support:196,explorer:136}[a.job];if(id&&a.level>=(sp.at||20)){a.id=id;a.action=null;stats(a);a.hp=a.max;fx('star',a.x,a.y,4,1.2);toast('¡'+a.name+' evolucionó a '+S[a.id].name+'!');}}
function bossFloor(){return g.floor>=10&&g.floor%5===0;}
function stage(){return g?.route[Math.min(14,g.floor<10?0:Math.ceil((g.floor-10)/5))]||ECOS_STAGES[0];}
function active(){return players.filter(a=>!a.down&&!a.disconnected);}
function me(){return players.find(a=>a.pid===myPid)||players[0];}
const T=48;
function seeded(seed){let v=seed>>>0;return()=>{v=(v*1664525+1013904223)>>>0;return v/4294967296;};}
function tileIndex(tx,ty){return ty*g.mw+tx;}
function walk(tx,ty){return tx>=0&&ty>=0&&tx<g.mw&&ty<g.mh&&g.map[tileIndex(tx,ty)]===1;}
function tileAt(x,y){return walk(Math.floor(x/T),Math.floor(y/T));}
function carve(x,y,w,h){for(let yy=y;yy<y+h;yy++)for(let xx=x;xx<x+w;xx++)if(xx>0&&yy>0&&xx<g.mw-1&&yy<g.mh-1)g.map[tileIndex(xx,yy)]=1;}
function generateFloor(){const rng=seeded(g.seed+g.floor*7919),ri=(a,b)=>a+Math.floor(rng()*(b-a+1));g.rooms=[];g.chests=[];g.bossDefeated=false;g.blueWave=0;g.stairsKnown=false;g.mw=bossFloor()?40:84;g.mh=bossFloor()?30:69;g.map=Array(g.mw*g.mh).fill(0);g.fog=Array(g.map.length).fill(0);
 if(bossFloor()){const r={x:4,y:4,w:32,h:22,cx:20,cy:15};g.rooms=[r];carve(r.x,r.y,r.w,r.h);g.spawn={x:20*T,y:23*T};g.stairs={x:20*T,y:7*T};return;}
 for(let y=0;y<3;y++)for(let x=0;x<3;x++){const r={x:3+x*26+ri(0,4),y:3+y*21+ri(0,3),w:ri(14,19),h:ri(10,14),gx:x,gy:y};r.cx=r.x+Math.floor(r.w/2);r.cy=r.y+Math.floor(r.h/2);g.rooms.push(r);carve(r.x,r.y,r.w,r.h);}
 const edges=[];for(let i=0;i<9;i++){if(i%3<2)edges.push([i,i+1]);if(i<6)edges.push([i,i+3]);}edges.sort(()=>rng()-.5);const roots=Array.from({length:9},(_,i)=>i),root=x=>{while(roots[x]!==x)x=roots[x];return x;};const chosen=[];for(const [a,b] of edges)if(root(a)!==root(b)){roots[root(a)]=root(b);chosen.push([a,b]);}for(const edge of edges)if(!chosen.some(e=>e[0]===edge[0]&&e[1]===edge[1])&&rng()<.45)chosen.push(edge);
 for(const [a,b] of chosen){const r=g.rooms[a],s=g.rooms[b];if(rng()<.5){carve(Math.min(r.cx,s.cx)-1,r.cy-1,Math.abs(r.cx-s.cx)+3,3);carve(s.cx-1,Math.min(r.cy,s.cy)-1,3,Math.abs(r.cy-s.cy)+3);}else{carve(r.cx-1,Math.min(r.cy,s.cy)-1,3,Math.abs(r.cy-s.cy)+3);carve(Math.min(r.cx,s.cx)-1,s.cy-1,Math.abs(r.cx-s.cx)+3,3);}}
 const first=g.rooms[0];g.spawn={x:first.cx*T+24,y:first.cy*T+24};const distances=Array(g.map.length).fill(-1),queue=[[first.cx,first.cy]];distances[tileIndex(first.cx,first.cy)]=0;for(let qi=0;qi<queue.length;qi++){const [x,y]=queue[qi];for(const [dx,dy] of [[1,0],[-1,0],[0,1],[0,-1]])if(walk(x+dx,y+dy)&&distances[tileIndex(x+dx,y+dy)]<0){distances[tileIndex(x+dx,y+dy)]=distances[tileIndex(x,y)]+1;queue.push([x+dx,y+dy]);}}
 const far=g.rooms.slice(1).sort((a,b)=>distances[tileIndex(b.cx,b.cy)]-distances[tileIndex(a.cx,a.cy)])[0];g.stairs={x:far.cx*T+24,y:far.cy*T+24};
 for(let i=1;i<g.rooms.length;i++){const r=g.rooms[i];if(r!==far||i%2===0)g.chests.push({id:'c'+i,x:(r.cx-3)*T+24,y:r.cy*T+24,opened:false});}
}
function enemy(id,x,y,boss=false){const team=1+Math.max(0,active().length-1)*.55;const hp=(boss?200+g.floor*13:28+g.floor*2.1)*team;return{eid:Math.random().toString(36).slice(2,10),id,x,y,prevX:x,prevY:y,r:boss?29:16,hp,max:hp,bar:hp,boss,dir:0,anim:0,hurt:0,flash:0,cd:rnd(.8,2.3),wind:0,cycle:0,stun:0,charge:0,vx:0,vy:0,action:null,warning:null,dead:0,moving:false,leap:null};}
function nextFloor(first=false){enemies=[];shots=[];effects=[];loot=[];hazards=[];tasks=[];generateFloor();g.revision++;for(const [i,a] of players.entries()){a.x=g.spawn.x+(i%2)*45-20;a.y=g.spawn.y+Math.floor(i/2)*42;a.prevX=a.x;a.prevY=a.y;a.vx=0;a.vy=0;a.action=null;a.inv=1.4;a.input=0;a.oldInput=0;if(!first){gainXP(a,18+g.floor*2);a.hp=Math.min(a.max,a.hp+Math.round(a.max*.12));}if(a.down){a.down=false;a.hp=Math.round(a.max*.5);}}
 if(bossFloor())spawnBoss();else for(let i=1;i<g.rooms.length;i++){const r=g.rooms[i];const count=2+Math.floor(g.floor/25);for(let j=0;j<count;j++){const x=(r.x+2+Math.random()*(r.w-4))*T,y=(r.y+2+Math.random()*(r.h-4))*T;enemies.push(enemy(pick(stage().pool),x,y));}if(i%2===0)loot.push({lid:'floor'+i,x:(r.cx+3)*T,y:(r.cy+2)*T,key:pick(['potion','ether','oran_berry','protein','carbos','scope_lens']),taken:false});}
 camera.x=players[0].x;camera.y=players[0].y;reveal();if(NET.role==='host'){NET.world(packWorld());NET.state(packState());}hud();}
function spawnBoss(){const def=stage(),id=def.blue?[3,9,6][g.blueWave]:def.id;const b=enemy(id,20*T,10*T,true);b.kind=def.blue?['leaf','water','fire'][g.blueWave]:def.kind;b.mode=def.blue?['garden','spiral','charge'][g.blueWave]:def.mode;b.name=RPG_BOSS_NAMES[id];if(def.blue){b.hp*=.72;b.max=b.hp;}enemies.push(b);toast((def.blue?'Blue envía a ':def.leader+' · ')+b.name);}
function reveal(){if(!g)return;for(const a of active()){const tx=Math.floor(a.x/T),ty=Math.floor(a.y/T),r=a.job==='explorer'?12:9;for(let y=Math.max(0,ty-r);y<=Math.min(g.mh-1,ty+r);y++)for(let x=Math.max(0,tx-r);x<=Math.min(g.mw-1,tx+r);x++)if((x-tx)**2+(y-ty)**2<=r*r)g.fog[tileIndex(x,y)]=1;if(distance(a,g.stairs)<r*T)g.stairsKnown=true;}}
