function nearTarget(a,max=700){let best=null,dd=max;for(const e of enemies)if(e.hp>0&&distance(a,e)<dd){dd=distance(a,e);best=e;}return best;}
function fx(kind,x,y,size=1,total=.4){effects.push({kind,x,y,size,life:total,total});}
function art(a,name){return actorArt[a.id]?.[name]||(['Shoot','Charge'].includes(name)?actorArt[a.id]?.Attack:null)||actorArt[a.id]?.Idle||actorArt[a.id]?.Walk;}
function action(a,name,fn,duration=.4){if(a.action)return false;const anim=art(a,name);const total=duration,hit=anim?clamp(anim.dur.slice(0,Math.min(anim.hit,anim.dur.length-1)).reduce((x,y)=>x+y,0)/anim.total,.18,.7)*total:total*.3;a.action={name,t:0,total,hit,done:false,fn};return true;}
function animate(a,dt){a.anim=(a.anim||0)+dt;a.hurt=Math.max(0,(a.hurt||0)-dt);a.flash=Math.max(0,(a.flash||0)-dt);if(a.action){const act=a.action;act.t+=dt;if(!act.done&&act.t>=act.hit){act.done=true;act.fn?.();}if(act.t>=act.total&&a.action===act)a.action=null;}}
function fire(owner,a,speed,damage,kind,x=owner.x,y=owner.y,options={}){shots.push({bid:g.runId+'-'+(g.shotId=(g.shotId||0)+1),x,y,prevX:x,prevY:y,vx:Math.cos(a)*speed,vy:Math.sin(a)*speed,kind,d:damage,owner:owner.pid||null,hostile:!owner.pid,age:0,life:2.5,r:kind==='rock'?9:7,level:owner.level,hits:[],...options});}
function dealt(a,base){return base*(a.buff>0?1.35:1)*(Math.random()<a.crit?1.6:1);}
function attack(a){if(a.cool>0||a.action||a.burst>0||a.down)return;const target=nearTarget(a),angle=target?Math.atan2(target.y-a.y,target.x-a.x):a.aim??Math.PI/2;if(Math.hypot(a.vx,a.vy)<8)face(a,Math.cos(angle),Math.sin(angle));a.cool=a.buff>0?.24:.4;action(a,S[a.id].kind==='hit'?'Attack':'Shoot',()=>{if(S[a.id].kind==='hit'){fx('hit',a.x+Math.cos(angle)*35,a.y+Math.sin(angle)*35,1.2,.3);for(const e of enemies)if(e.hp>0&&distance(a,e)<105)hurt(e,dealt(a,a.damage*1.65));}else fire(a,angle,440,dealt(a,a.damage),S[a.id].kind,a.x+Math.cos(angle)*25,a.y+Math.sin(angle)*25);},a.cool*.93);}
function special(a,key){if(a[key]>0||a.action||a.down||a.burst>0)return;if(key==='e'&&a.level<10){if(a.pid===myPid)toast('El segundo movimiento se desbloquea al nivel 10.');a.e=1;return;}a[key]=key==='q'?5.5:8;const target=nearTarget(a),angle=target?Math.atan2(target.y-a.y,target.x-a.x):a.aim??Math.PI/2,kind=S[a.id].kind;if(Math.hypot(a.vx,a.vy)<8)face(a,Math.cos(angle),Math.sin(angle));action(a,key==='q'?'Charge':'Shoot',()=>{if(key==='q'){if(kind==='hit'){a.burst=.24;a.vx=Math.cos(angle)*650;a.vy=Math.sin(angle)*650;a.inv=.5;}else if(kind==='water'){a.shield=3.2;fx('water',a.x,a.y,3,.7);}else{fx(kind==='spark'?'discharge':kind,a.x,a.y,2.6,.6);for(const e of enemies)if(e.hp>0&&distance(a,e)<170){hurt(e,dealt(a,a.damage*1.5));if(kind==='spark'||kind==='leaf')e.stun=1.6;}}}else{const count=kind==='hit'?12:kind==='fire'?5:8;for(let i=0;i<count;i++){const ang=kind==='fire'?angle+(i-2)*.14:i*Math.PI*2/count;fire(a,ang,kind==='fire'?450:330,dealt(a,a.damage*1.35),kind==='hit'?'star':kind,a.x,a.y,{size:1.3});}}},.5);}
function classSkill(a){if(a.rskill>0||a.down)return;a.rskill=C[a.job].cool;if(a.job==='guardian'){for(const b of active())if(distance(a,b)<300)b.shield=5;fx('discharge',a.x,a.y,3.5,.8);toast(a.name+' protege al equipo.');}else if(a.job==='striker'){a.buff=6;fx('star',a.x,a.y,3,.65);}else if(a.job==='support'){for(const b of active())if(distance(a,b)<340)b.hp=Math.min(b.max,b.hp+b.max*.27);fx('water',a.x,a.y,5,.8);toast('Pulso Vital · curación de equipo');}else{g.stairsKnown=true;for(const c of g.chests){const tx=Math.floor(c.x/T),ty=Math.floor(c.y/T);g.fog[tileIndex(tx,ty)]=1;}fx('star',a.x,a.y,4,.8);toast('Rastreo · escaleras y tesoros señalados');}}
function creditCoins(runId,total){try{const current=JSON.parse(localStorage.getItem('ecosMeta'));if(current&&Number.isFinite(current.bank)&&Array.isArray(current.unlocked)){meta.bank=current.bank;meta.unlocked=[...new Set([...meta.unlocked,...current.unlocked.filter(id=>window.KANTO_DEX?.[id]?.buyable)])];}const ledger=JSON.parse(localStorage.getItem('ecosRunCredits')||'{}'),paid=Number(ledger[runId])||0,delta=Math.max(0,total-paid);meta.bank+=delta;ledger[runId]=Math.max(paid,total);const entries=Object.entries(ledger).slice(-64);localStorage.setItem('ecosRunCredits',JSON.stringify(Object.fromEntries(entries)));saveMeta();}catch{meta.bank+=Math.max(0,total-(g?.localCredit||0));if(g)g.localCredit=total;saveMeta();}}
function award(n){for(const a of players)if(!a.disconnected)a.coins+=n;creditCoins(g.runId,players[0]?.coins||0);}
function hurt(e,d){if(e.hp<=0)return;e.hp-=d;e.hurt=.16;e.flash=.09;fx('hit',e.x,e.y,.8,.2);if(e.hp<=0){e.dead=.6;e.action=null;g.kills++;award(e.boss?50:3);for(const a of players)gainXP(a,e.boss?100+g.floor*3:12+Math.floor(g.floor/4));fx('smash',e.x,e.y,1.1,.5);if(!e.boss&&Math.random()<.35)loot.push({lid:e.eid,x:e.x,y:e.y,key:pick(['potion','oran_berry','ether','sitrus_berry']),taken:false});if(e.boss){hazards=[];shots=shots.filter(b=>!b.hostile);tasks=[];if(stage().blue&&g.blueWave<2){g.blueWave++;tasks.push({time:2,kind:'blueNext'});toast(e.name+' vencido · Blue prepara su siguiente Pokémon.');}else{g.bossDefeated=true;toast((stage().blue?'Blue':e.name)+' vencido. Busca las escaleras para continuar.');}}}}
function damage(a,d,kind='hit'){if(a.inv>0||a.down||a.disconnected)return;let reduce=a.job==='guardian'?.78:1;if(a.shield>0)reduce*=.45;a.hp-=d*reduce;a.inv=.75;a.hurt=.22;a.flash=.18;a.combat=4;fx(kind,a.x,a.y,1,.3);if(a.hp<=0){if(a.bag.revive>0){a.bag.revive--;a.hp=a.max*.35;a.inv=2;toast('Revivir salvó a '+a.name+'.');}else{a.hp=0;a.down=true;a.action=null;a.vx=0;a.vy=0;toast(a.name+' cayó. Mantén F cerca para rescatarlo.');if(!active().length){if(players.some(p=>p.disconnected)){if(!g.wipeWait){const run=g;g.wipeWait=true;toast('Todos cayeron. Se espera 45 s por un jugador desconectado…');setTimeout(()=>{run.wipeWait=false;if(g===run&&!g.ended&&!active().length)finish(false);},45000);}}else finish(false);}}}}
function useItem(a,key){if(a.down||!ITEMS[key]||!(a.bag[key]>0))return;const it=ITEMS[key];if(it.type!=='use')return;if(it.heal||it.ratio){if(a.hp>=a.max){if(a.pid===myPid)toast('Tus PS ya están completos.');return;}a.hp=Math.min(a.max,a.hp+(it.heal||a.max*it.ratio));fx('water',a.x,a.y,2,.4);}if(it.ether){a.q=0;a.e=0;}a.bag[key]--;if(a.pid===myPid)toast(it.name+' utilizado');}
function equip(a,key){if(!ITEMS[key]||ITEMS[key].type!=='gear'||!(a.bag[key]>0))return;const index=a.gear.indexOf(key);if(index>=0)a.gear.splice(index,1);else if(a.gear.length<3)a.gear.push(key);else{if(a.pid===myPid)toast('Solo puedes equipar tres objetos. Quita uno primero.');return;}stats(a);}
