 if(a.burst>0){a.burst-=dt;move(a,a.vx*dt,a.vy*dt);if(Math.random()<dt*30)effects.push({after:true,id:a.id,dir:a.dir,x:a.x,y:a.y,life:.17,total:.17});}else{const speed=a.speed*(a.action?.75:1),ease=1-Math.exp(-18*dt);a.vx+=(dx*speed-a.vx)*ease;a.vy+=(dy*speed-a.vy)*ease;if(Math.hypot(a.vx,a.vy)<1.5){a.vx=0;a.vy=0;}move(a,a.vx*dt,a.vy*dt);}
